    @staticmethod
    def _decimal_to_base_string(decimal_num, base, prefix):
        return f"{decimal_num:o}" if base == 8 else f"{decimal_num:x}" if base == 16 else f"{decimal_num:b}"

    @staticmethod
    def _base_string_to_decimal(plain_string, base):
